#!/usr/bin/env python3
"""Render course JSON to a standalone offline HTML player. No third-party modules."""
import json,sys,html,re
from pathlib import Path
sys.path.insert(0,str(Path(__file__).parent))

def build(input_file,output_file):
 data=json.loads(Path(input_file).read_text(encoding='utf-8'))
 from validate_course import validate
 errors,lessons=validate(data)
 if errors:raise ValueError('\n'.join(errors))
 safe=json.dumps(data,ensure_ascii=False).replace('</','<\\/')
 page=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>__TITLE__</title><style>
:root{font-family:system-ui,-apple-system,Segoe UI,sans-serif;color:#172b46;background:#edf3f9}*{box-sizing:border-box}button,select{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible{outline:3px solid #f5ac36;outline-offset:2px}header{background:#102b4d;color:white;padding:15px 22px;display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.brand{font-size:22px;font-weight:800}header small{color:#bed1e7}.headerbuttons{display:flex;gap:9px;flex-wrap:wrap}.btn{background:white;color:#183b61;border:1px solid #b8cee5;border-radius:9px;padding:9px 14px;font-weight:650}.btn.main{background:#2584d8;color:white;border-color:#2584d8}.shell{max-width:1700px;margin:auto;display:grid;grid-template-columns:286px minmax(0,1fr) 268px;gap:13px;padding:13px;align-items:start}.panel{background:white;border:1px solid #d9e4ef;box-shadow:0 9px 26px #142d5110;border-radius:14px}.left{padding:14px;position:sticky;top:13px;max-height:calc(100vh - 26px);overflow:auto}.left h2{font-size:15px;margin:4px 0 5px}.muted{font-size:12px;color:#637a94}.mod{font-weight:750;font-size:13px;background:#edf4fc;padding:10px;border-radius:8px;margin:12px 0 5px}.nav{display:block;width:100%;border:0;background:transparent;text-align:left;border-radius:8px;padding:8px 10px;color:#4b637b;font-size:13px;line-height:1.45}.nav.active{background:#dceefd;color:#13477d;font-weight:750}.nav:hover{background:#eff6fc}.content{padding:26px 32px;min-height:80vh}.content h1{font-size:30px;margin:6px 0 8px;line-height:1.15}.content h2{font-size:21px;margin:28px 0 12px}.content h3{font-size:17px;margin:12px 0}.content p,.content li{line-height:1.75;font-size:15px}.content .intro{font-size:17px;color:#546982}.kicker{text-transform:uppercase;letter-spacing:.13em;font-size:11px;color:#4d7097;font-weight:800}.chip{font-size:12px;background:#e8f5ff;color:#175487;border-radius:99px;padding:6px 9px}.info{background:#f2f7fd;border:1px solid #dbe9f7;border-radius:12px;padding:17px 19px;margin:17px 0}.info h3{margin-top:0}.story{border-left:4px solid #23a294;background:#effbf9;padding:17px 19px;margin:20px 0;border-radius:0 10px 10px 0}.example{border:1px solid #dbe7f4;border-radius:12px;padding:15px 18px;margin:15px 0;background:#fff}.scene{background:#142d4e;color:white;border-radius:14px;padding:19px;margin:18px 0}.sceneBar{display:flex;justify-content:space-between;gap:15px;align-items:center;flex-wrap:wrap}.sceneBar strong{font-size:18px}.sceneBody{background:#203f67;border-radius:12px;min-height:210px;margin-top:13px;padding:20px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:14px}.sceneVisual{display:flex;flex-wrap:wrap;justify-content:center;align-items:center;gap:12px;min-height:64px}.token{background:#3688d2;color:white;border:1px solid #78b6ec;border-radius:10px;padding:15px;font-weight:750;font-size:16px;animation:flyin .5s both}.eq{font-size:26px;font-weight:800;letter-spacing:.02em}.barBox{display:flex;align-items:flex-end;gap:14px}.bar{min-width:58px;padding:4px;background:#39a6ae;border-radius:7px 7px 0 0;color:white;display:flex;align-items:flex-end;justify-content:center;font-weight:800;font-size:12px}.sceneText{line-height:1.7;font-size:16px;color:#e9f2fb;max-width:730px}.sceneBtns{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.sceneBtns button{flex:1;min-width:100px}.note{font-size:12px;color:#bcd4ed;line-height:1.5;margin-top:12px}.speakCue{outline:3px solid #ffbd4a;outline-offset:4px;box-shadow:0 0 0 7px #ffbd4a24}.practiceQuestion{border:1px solid #dbe5f1;border-radius:12px;padding:17px;margin:15px 0}.answerGrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin-top:12px}.answerGrid button{text-align:left;background:#f8fbff;border:1px solid #b6cfe4;border-radius:8px;padding:12px;color:#193d62}.answerGrid button.correct{background:#dcf9e5;border-color:#37a36e}.answerGrid button.wrong{background:#ffe9e6;border-color:#df7e73}.answerGrid button:disabled{opacity:.85}.feedback{color:#315976;font-size:13px;margin:8px 0}.right{padding:17px;position:sticky;top:13px;max-height:calc(100vh - 26px);overflow:auto}.right h3{font-size:16px;margin:3px 0}.right a{display:block;font-size:13px;margin:11px 0;line-height:1.5}.right p{font-size:13px;line-height:1.6;color:#60748a}.hideRight .shell{grid-template-columns:286px minmax(0,1fr)}.hideRight .right,.isPractice .right{display:none}.isPractice .shell{grid-template-columns:286px minmax(0,1fr)}.foot{padding:15px;text-align:center;color:#61758c;font-size:12px}.navFooter{display:flex;justify-content:space-between;gap:12px;margin-top:25px}.section{scroll-margin-top:15px}.sectionSpeaking{outline:3px solid #f6b842;outline-offset:5px;border-radius:8px}.warning{background:#fff7e7;border:1px solid #f0d7a3;border-radius:8px;padding:11px;color:#735b28;font-size:13px;line-height:1.5}code,pre{font-family:ui-monospace,Consolas,monospace}pre{white-space:pre-wrap;background:#10243d;color:#e1ecf8;padding:15px;border-radius:8px;overflow:auto}.objectiveList{margin-top:6px}.progress{font-size:12px;color:#d3e6fa}@keyframes flyin{from{opacity:.1;transform:translateY(13px)}to{opacity:1;transform:none}}@media(max-width:1100px){.shell{grid-template-columns:250px minmax(0,1fr)}.right{display:none}.hideRight .shell,.isPractice .shell{grid-template-columns:250px minmax(0,1fr)}}@media(max-width:680px){.shell,.hideRight .shell,.isPractice .shell{display:block;padding:8px}.left{position:static;max-height:300px;margin-bottom:10px}.content{padding:18px}.content h1{font-size:25px}.answerGrid{grid-template-columns:1fr}header{padding:12px}.brand{font-size:18px}}@media(prefers-reduced-motion:reduce){*{animation:none!important;scroll-behavior:auto!important}}
</style></head><body><header><div><div class="brand">◈ Training Generator</div><small id="courseTitle"></small></div><div class="headerbuttons"><span class="progress" id="progress"></span><button class="btn" id="resourceBtn" aria-pressed="true">☷ Hide resources</button><button class="btn main" id="practiceBtn">✎ Practice Time</button><button class="btn" id="exportBtn">Export progress</button></div></header><div id="app"><div class="shell"><aside class="left panel"><h2>Complete course index</h2><div class="muted" id="indexNote"></div><div id="index"></div></aside><main class="content panel" id="lesson" aria-live="polite"></main><aside class="right panel" id="resources"><h3>Further reading (availability varies)</h3><div id="resourceLinks"></div><div class="warning">External resources require internet. Their inclusion does not mean their content is bundled into this offline course.</div><h3 style="margin-top:18px">Voice quality</h3><p>This package uses browser/system speech voices unless neural audio files have been bundled. It does not include a natural Chatterbox or Qwen3 voice.</p></aside></div><footer class="foot">Offline course player · Evidence-backed review required before publishing a complete accredited course</footer></div><script>
const COURSE=__DATA__;
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const lessons=COURSE.modules.flatMap((m,mi)=>m.lessons.map((l,li)=>({...l,mi,li,mod:m.title,status:l.status||'generated'})));
const ready=i=>lessons[i]?.status!=='planned';const validIndices=lessons.map((l,i)=>ready(i)?i:-1).filter(i=>i>=0);
let selection=validIndices[0]??0,practice=false,rightVisible=true,scene=0,speechRun=0,isSpeaking=false,speechPaused=false,answered={},questions=[],voiceName='',practiceSeed=0;
const progressKey='tg-v02-'+COURSE.title+'-'+lessons.map(l=>l.title).join('|').split('').reduce((h,c)=>((h*31+c.charCodeAt(0))>>>0),17).toString(16);let progress={};try{progress=JSON.parse(localStorage.getItem(progressKey)||'{}')}catch(e){}
function save(){try{localStorage.setItem(progressKey,JSON.stringify(progress))}catch(e){}}
function stopSpeech(){speechRun++;isSpeaking=false;speechPaused=false;if('speechSynthesis'in window)speechSynthesis.cancel();document.querySelectorAll('.sectionSpeaking,.speakCue').forEach(e=>e.classList.remove('sectionSpeaking','speakCue'))}
function index(){let offset=0;$('index').innerHTML=COURSE.modules.map((m,i)=>{let out='<div class="mod">'+String(i+1).padStart(2,'0')+' '+esc(m.title)+'</div>';m.lessons.forEach((l,j)=>{let k=offset+j;out+='<button class="nav '+(!practice&&selection===k?'active':'')+'" data-lesson="'+k+'" '+(ready(k)?'':'disabled title="Planned - not yet generated"')+'>'+(progress[k]?'✓ ':'')+(i+1)+'.'+(j+1)+' '+esc(l.title)+(ready(k)?'':' · Planned')+'</button>'});offset+=m.lessons.length;return out}).join('');$('indexNote').textContent=COURSE.modules.length+' modules · '+validIndices.length+' generated · '+(lessons.length-validIndices.length)+' planned';$('progress').textContent=validIndices.filter(k=>progress[k]).length+'/'+validIndices.length+' completed';document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>go(Number(b.dataset.lesson)))}
function sceneVisual(v){if(!v)return '';if(v.type==='equation')return '<div class="eq">'+esc(v.text)+'</div>';if(v.type==='bars')return '<div class="barBox">'+v.items.map(x=>'<div><div class="bar" style="height:'+Math.max(25,Math.min(150,140*(parseFloat(x.value)||0)/Math.max(1,...v.items.map(t=>parseFloat(t.value)||0))))+'px">'+esc(x.value)+'</div><small>'+esc(x.label)+'</small></div>').join('')+'</div>';return v.items.map(x=>'<div class="token">'+esc(x)+'</div>').join('')}
function showScene(k){let l=lessons[selection];scene=Math.max(0,Math.min(k,l.scenes.length-1));let s=l.scenes[scene];$('sceneStep').textContent='Step '+(scene+1)+' of '+l.scenes.length+' · '+s.title;$('sceneGraphic').innerHTML=sceneVisual(s.visual);$('sceneNarration').textContent=s.narration;document.querySelectorAll('.speakCue').forEach(x=>x.classList.remove('speakCue'));$('sceneBody').classList.add('speakCue')}
function speak(){stopSpeech();const l=lessons[selection];let run=speechRun;isSpeaking=true;function next(i){if(!isSpeaking||run!==speechRun)return;if(i>=l.scenes.length){isSpeaking=false;$('speechState').textContent='Lesson narration complete. Replay whenever you like.';return}showScene(i);$('speechState').textContent='Reading: '+l.scenes[i].title+' · '+(i+1)+'/'+l.scenes.length;if(!('speechSynthesis'in window)){$('speechState').textContent='Speech not supported. Use the visual Next step button.';return}let u=new SpeechSynthesisUtterance(l.scenes[i].narration);let available=speechSynthesis.getVoices();let chosen=available.find(v=>v.name===voiceName);if(chosen)u.voice=chosen;u.lang=u.voice?.lang||'en-US';u.rate=.95;u.onend=()=>{if(run===speechRun)next(i+1)};u.onerror=()=>{if(run===speechRun){isSpeaking=false;$('speechState').textContent='Speech failed. Select another system voice or use Next step.'}};let pieces=[];for(const sentence of (l.scenes[i].narration.match(/[^.!?]+[.!?]*/g)||[])){let rest=sentence.trim();while(rest.length>160){let cut=rest.lastIndexOf(' ',160);if(cut<30)cut=rest.indexOf(' ',160);if(cut<0)break;pieces.push(rest.slice(0,cut).trim());rest=rest.slice(cut+1).trim()}if(rest)pieces.push(rest)};let part=0;function chunk(){if(run!==speechRun||!isSpeaking)return;if(part>=pieces.length){next(i+1);return}let piece=new SpeechSynthesisUtterance(pieces[part++]);piece.voice=u.voice;piece.lang=u.lang;piece.rate=u.rate;piece.onend=chunk;piece.onerror=()=>{$('speechState').textContent='Speech unavailable; use visual controls.';isSpeaking=false};speechSynthesis.speak(piece)}chunk()}next(0)}
function voices(){if(!('speechSynthesis'in window))return;const v=speechSynthesis.getVoices();let s=$('voiceChoice');if(!s)return;s.innerHTML='<option value="">Default voice</option>'+v.map(x=>'<option value="'+esc(x.name)+'" '+(voiceName===x.name?'selected':'')+'>'+esc(x.name+' ('+x.lang+')')+'</option>').join('')}
function renderQuestion(q,key){return '<section class="practiceQuestion" data-q="'+key+'"><strong>'+esc(q.prompt)+'</strong><div class="answerGrid">'+q.choices.map((c,j)=>'<button data-answer="'+j+'">'+esc(c)+'</button>').join('')+'</div><p class="feedback" aria-live="polite"></p></section>'}
function wireQuestions(){document.querySelectorAll('.practiceQuestion').forEach(box=>{let key=box.dataset.q;let q=questions[Number(key.split(':').pop())];box.querySelectorAll('button').forEach(b=>b.onclick=()=>{if(box.dataset.attempted)return;box.dataset.attempted='1';let correct=Number(b.dataset.answer)===q.answer;b.classList.add(correct?'correct':'wrong');box.querySelectorAll('button').forEach(x=>x.disabled=true);box.querySelector('.feedback').textContent=(correct?'Correct. ':'Not quite. ')+q.reason;if(!correct&&!practice){let retry=document.createElement('button');retry.className='btn';retry.textContent='Try another attempt';retry.onclick=()=>{box.querySelector('.feedback').textContent='';delete box.dataset.attempted;box.querySelectorAll('.answerGrid button').forEach(x=>{x.disabled=false;x.classList.remove('wrong','correct')});retry.remove()};box.appendChild(retry)}if(correct){box.querySelectorAll('button').forEach(x=>x.disabled=true);answered[key]=true;let prefix='lesson:'+selection+':';if(!practice&&Object.keys(answered).filter(k=>k.startsWith(prefix)).length>=lessons[selection].questions.length){progress[selection]=true;save();index()}}})})}
function resource(l){$('resourceLinks').innerHTML=l.resources.length?l.resources.map(r=>'<a href="'+esc(r.url)+'" target="_blank" rel="noopener noreferrer">'+esc(r.title)+' ↗</a>').join(''):'<p>No externally verified links bundled for this lesson.</p>'}
function lesson(){stopSpeech();answered={};let l=lessons[selection];questions=l.questions;resource(l);$('lesson').innerHTML='<div class="kicker">MODULE '+(l.mi+1)+' · LESSON '+(l.li+1)+'</div><h1>'+esc(l.title)+'</h1><p class="intro">'+esc(COURSE.description||'')+'</p><div class="info"><h3>What you will be able to do</h3><ul class="objectiveList">'+l.objectives.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></div><div class="story section" id="hook"><strong>Why this matters</strong><p>'+esc(l.hook)+'</p></div><h2>Learn the concepts</h2>'+l.explanation.map((p,i)=>typeof p==='object'&&p.type==='code'?'<pre class="section" id="p'+i+'"><code>'+esc(p.text)+'</code></pre>':'<p class="section" id="p'+i+'">'+esc(typeof p==='object'?p.text:p)+'</p>').join('')+'<h2>Watch, listen and explore</h2><div class="scene"><div class="sceneBar"><strong>Guided concept demonstration</strong><span class="chip" id="sceneStep"></span></div><div class="sceneBody" id="sceneBody"><div class="sceneVisual" id="sceneGraphic"></div><p class="sceneText" id="sceneNarration"></p></div><div class="sceneBtns"><button class="btn main" id="play">▶ Play lesson</button><button class="btn" id="pause">⏸ Pause</button><button class="btn" id="replay">↺ Replay</button><button class="btn" id="prevStep">← Step</button><button class="btn" id="nextStep">Next step →</button></div><p class="note" id="speechState">Press Play to hear narration and see the corresponding visual. Browser voices may sound robotic.</p><label class="note">System voice: <select id="voiceChoice" aria-label="Select a system voice"><option>Default voice</option></select></label></div><h2>Worked examples</h2>'+l.examples.map((x,i)=>'<section class="example"><h3>Example '+(i+1)+': '+esc(x.title)+'</h3>'+(Array.isArray(x.walkthrough)?x.walkthrough:[x.walkthrough]).map(w=>typeof w==='object'&&w.type==='code'?'<pre><code>'+esc(w.text)+'</code></pre>':'<p>'+esc(typeof w==='object'?w.text:w)+'</p>').join('')+'</section>').join('')+'<div class="info"><h3>'+esc(l.lab.title)+'</h3><p>'+esc(l.lab.instructions)+'</p><strong>Completion check:</strong><p>'+esc(l.lab.success)+'</p></div><h2>Common pitfalls</h2><ul>'+l.pitfalls.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>'+((l.practical_application||l.corporate_application)?'<section class="story section" id="practical-application"><h2>'+esc((l.practical_application||{}).title||'Application In The Corporate World')+'</h2><h3>'+esc((l.practical_application||l.corporate_application).scenario_title)+'</h3><p>'+esc((l.practical_application||l.corporate_application).scenario)+'</p></section>':'')+'<h2>Check your understanding</h2>'+l.questions.map((x,j)=>renderQuestion(x,'lesson:'+selection+':'+j)).join('')+'<div class="info"><h3>Apply it</h3><p>'+esc(l.challenge)+'</p></div>'+(l.evidence_note?'<div class="warning"><strong>Evidence:</strong> '+esc(l.evidence_note)+'</div>':'')+'<div class="navFooter"><button class="btn" id="previous">← Previous lesson</button><button class="btn main" id="following">Next lesson →</button></div>';
showScene(0);voices();$('voiceChoice').onchange=e=>{voiceName=e.target.value};if('speechSynthesis'in window)speechSynthesis.onvoiceschanged=voices;$('play').onclick=speak;$('replay').onclick=speak;$('pause').onclick=()=>{if(!('speechSynthesis'in window))return;if(speechPaused){speechSynthesis.resume();speechPaused=false;$('pause').textContent='⏸ Pause'}else{speechSynthesis.pause();speechPaused=true;$('pause').textContent='▶ Resume'}};$('nextStep').onclick=()=>{stopSpeech();showScene(scene+1)};$('prevStep').onclick=()=>{stopSpeech();showScene(scene-1)};$('previous').onclick=()=>go([...validIndices].reverse().find(i=>i<selection)??selection);$('following').onclick=()=>go(validIndices.find(i=>i>selection)??selection);$('previous').disabled=!validIndices.some(i=>i<selection);$('following').disabled=!validIndices.some(i=>i>selection);wireQuestions()}
function practiceView(){stopSpeech();let all=lessons.flatMap((l,i)=>(l.questions||[]).map(q=>({...q,li:i})));const filter=$('practiceFilter')?.value||'-1';if(filter!=='-1')all=all.filter(q=>q.li===Number(filter));for(let i=all.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[all[i],all[j]]=[all[j],all[i]]};questions=all.slice(0,20);$('lesson').innerHTML='<div class="kicker">QUESTIONS ONLY</div><h1>✎ Practice Time</h1><p class="intro">Test your understanding without lesson explanations. The answer rationale appears after each attempt.</p><label>Choose a lesson: <select id="practiceFilter"><option value="-1">All lessons</option>'+lessons.filter(l=>l.status!=='planned').map(l=>'<option value="'+lessons.indexOf(l)+'" '+(String(lessons.indexOf(l))===filter?'selected':'')+'>'+esc(l.title)+'</option>').join('')+'</select></label><p class="muted">Showing '+questions.length+' of '+all.length+' questions</p><button class="btn" id="reshuffle">↻ Shuffle again</button>'+questions.map((q,i)=>renderQuestion(q,'practice:'+i)).join('');$('practiceFilter').onchange=practiceView;$('reshuffle').onclick=()=>{practiceSeed++;practiceView()};wireQuestions()}
function go(i){if(i<0||i>=lessons.length||!ready(i))return;selection=i;practice=false;render();scrollTo({top:0,behavior:'smooth'})}
function render(){index();$('app').className=(rightVisible?'':'hideRight ')+(practice?'isPractice':'');$('resourceBtn').textContent=rightVisible?'☷ Hide resources':'☷ Show resources';$('practiceBtn').textContent=practice?'← Back to course':'✎ Practice Time';$('resourceBtn').style.display=practice?'none':'';if(practice)practiceView();else lesson()}
$('courseTitle').textContent=COURSE.title+' · '+COURSE.status;$('resourceBtn').onclick=()=>{rightVisible=!rightVisible;render()};$('practiceBtn').onclick=()=>{practice=!practice;render()};$('exportBtn').onclick=()=>{const blob=new Blob([JSON.stringify({course:COURSE.title,progress,exported:new Date().toISOString()},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='training-generator-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};render();
</script></body></html>'''
 page=page.replace('__TITLE__',html.escape(data['title'])).replace('__DATA__',safe)
 Path(output_file).write_text(page,encoding='utf-8')
 print('Built',output_file,'(',len(lessons),'lessons)')
if __name__=='__main__':build(sys.argv[1],sys.argv[2])
